public inherited sharing class ContactTriggerHandler {
    public static void beforeInsert(List<Contact> newContacts) {
        populateAccountDetails(newContacts, true);
    }

    public static void beforeUpdate(List<Contact> newContacts) {
        populateAccountDetails(newContacts, false);
    }

    public static void afterInsert(List<Contact> newContacts) {
        updateAccountPhone(newContacts);
    }

    private static void populateAccountDetails(List<Contact> contacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                if (String.isBlank(c.MailingCountry) || (isInsert && String.isBlank(c.LeadSource))) {
                    accountIds.add(c.AccountId);
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : contacts) {
            if (c.AccountId != null && accountsById.containsKey(c.AccountId)) {
                Account a = accountsById.get(c.AccountId);
                if (String.isBlank(c.MailingCountry)) {
                    c.MailingCountry = a.BillingCountry;
                }
                if (isInsert && String.isBlank(c.LeadSource)) {
                    c.LeadSource = a.AccountSource;
                }
            }
        }
    }

    private static void updateAccountPhone(List<Contact> contacts) {
        Map<Id, String> accountPhonesToUpdate = new Map<Id, String>();

        for (Contact c : contacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                if (!accountPhonesToUpdate.containsKey(c.AccountId)) {
                    accountPhonesToUpdate.put(c.AccountId, c.Phone);
                }
            }
        }

        if (accountPhonesToUpdate.isEmpty()) {
            return;
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account a : [SELECT Id, Phone FROM Account WHERE Id IN :accountPhonesToUpdate.keySet()]) {
            if (String.isBlank(a.Phone)) {
                a.Phone = accountPhonesToUpdate.get(a.Id);
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
