public with sharing class ExchangeRateClient {
    public class ExchangeRateException extends Exception {}

    private static final Pattern CURRENCY_CODE_PATTERN = Pattern.compile('^[A-Z]{3}$');
    private static final String BASE_ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // Validate and normalise base currency
        if (baseCurrency == null) {
            throw new ExchangeRateException('Base currency code cannot be null.');
        }
        String normalizedBase = baseCurrency.trim().toUpperCase();
        if (!CURRENCY_CODE_PATTERN.matcher(normalizedBase).matches()) {
            throw new ExchangeRateException('Base currency code must be exactly three letters A-Z: ' + baseCurrency);
        }

        // Validate and normalise quote currencies
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currencies cannot be null or empty.');
        }
        Set<String> normalizedQuotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            if (quote == null) {
                throw new ExchangeRateException('Quote currency code cannot be null.');
            }
            String normalizedQuote = quote.trim().toUpperCase();
            if (!CURRENCY_CODE_PATTERN.matcher(normalizedQuote).matches()) {
                throw new ExchangeRateException('Quote currency code must be exactly three letters A-Z: ' + quote);
            }
            normalizedQuotes.add(normalizedQuote);
        }

        // Build endpoint with query parameters
        String symbolsParam = String.join(new List<String>(normalizedQuotes), ',');
        String endpoint = BASE_ENDPOINT + '?base=' + normalizedBase + '&symbols=' + symbolsParam;

        HttpRequest req = new HttpRequest();
        req.setEndpoint(endpoint);
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');

        Http http = new Http();
        HttpResponse res = http.send(req);

        // Retry once on 503
        if (res.getStatusCode() == 503) {
            res = http.send(req);
        }

        if (res.getStatusCode() != 200) {
            throw new ExchangeRateException('Callout failed with HTTP status ' + res.getStatusCode() + ': ' + res.getStatus());
        }

        // Parse response
        Map<String, Decimal> rateMap = new Map<String, Decimal>();
        try {
            Map<String, Object> body = (Map<String, Object>) JSON.deserializeUntyped(res.getBody());
            if (body == null || !body.containsKey('rates') || !(body.get('rates') instanceof Map<String, Object>)) {
                throw new ExchangeRateException('Response body does not contain valid rates object.');
            }

            Map<String, Object> rates = (Map<String, Object>) body.get('rates');
            for (String quote : normalizedQuotes) {
                if (!rates.containsKey(quote) || rates.get(quote) == null) {
                    throw new ExchangeRateException('Missing rate for requested quote currency: ' + quote);
                }
                Object rawRate = rates.get(quote);
                try {
                    rateMap.put(quote, Decimal.valueOf(String.valueOf(rawRate)));
                } catch (Exception ex) {
                    throw new ExchangeRateException('Could not parse rate value for ' + quote + ': ' + rawRate, ex);
                }
            }
        } catch (ExchangeRateException ex) {
            throw ex;
        } catch (Exception ex) {
            throw new ExchangeRateException('Failed to parse response body: ' + ex.getMessage(), ex);
        }

        return rateMap;
    }
}
