public with sharing class RecordSearchService {
    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            // Validate maxRows
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be an integer between 1 and 200.');
            }

            // Validate object existence
            if (String.isBlank(objectApiName)) {
                throw new SearchException('Object API name cannot be blank.');
            }

            String trimmedObjName = objectApiName.trim();
            Schema.DescribeSObjectResult objDescribe;
            try {
                List<Schema.DescribeSObjectResult> describes = Schema.describeSObjects(
                    new List<String>{ trimmedObjName }
                );
                if (describes != null && !describes.isEmpty()) {
                    objDescribe = describes[0];
                }
            } catch (Exception e) {
                Schema.SObjectType fallbackType = Schema.getGlobalDescribe().get(trimmedObjName);
                if (fallbackType != null) {
                    objDescribe = fallbackType.getDescribe();
                }
            }

            if (objDescribe == null) {
                throw new SearchException('Object does not exist: ' + objectApiName);
            }

            // Validate object read permission
            if (!objDescribe.isAccessible()) {
                throw new SearchException('Object is not accessible: ' + objectApiName);
            }

            Map<String, SObjectField> fieldMap = objDescribe.fields.getMap();

            // Validate Id field accessibility
            SObjectField idField = fieldMap.get('id');
            if (idField == null || !idField.getDescribe().isAccessible()) {
                throw new SearchException('Id field is not accessible for object: ' + objectApiName);
            }

            // Validate requested fields
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('Fields list cannot be null or empty.');
            }

            List<String> selectFields = new List<String>{ 'Id' };
            Set<String> seenFields = new Set<String>{ 'id' };

            for (String fieldName : fields) {
                if (String.isBlank(fieldName)) {
                    throw new SearchException('Field name cannot be blank.');
                }
                SObjectField sField = fieldMap.get(fieldName.trim());
                if (sField == null) {
                    throw new SearchException('Field does not exist: ' + fieldName);
                }
                DescribeFieldResult fDesc = sField.getDescribe();
                if (!fDesc.isAccessible()) {
                    throw new SearchException('Field is not accessible: ' + fieldName);
                }
                String canonicalName = fDesc.getName();
                if (!seenFields.contains(canonicalName.toLowerCase())) {
                    seenFields.add(canonicalName.toLowerCase());
                    selectFields.add(canonicalName);
                }
            }

            // Validate and build WHERE clause with bind variables
            List<String> whereClauses = new List<String>();
            Map<String, Object> bindVars = new Map<String, Object>();

            if (filters != null && !filters.isEmpty()) {
                Integer bindIndex = 0;
                for (String filterKey : filters.keySet()) {
                    if (String.isBlank(filterKey)) {
                        throw new SearchException('Filter key cannot be blank.');
                    }
                    SObjectField sField = fieldMap.get(filterKey.trim());
                    if (sField == null) {
                        throw new SearchException('Filter field does not exist: ' + filterKey);
                    }
                    DescribeFieldResult fDesc = sField.getDescribe();
                    if (!fDesc.isFilterable()) {
                        throw new SearchException('Filter field cannot be filtered: ' + filterKey);
                    }
                    if (!fDesc.isAccessible()) {
                        throw new SearchException('Filter field is not accessible: ' + filterKey);
                    }

                    String bindVarName = 'filterVal_' + bindIndex;
                    bindVars.put(bindVarName, filters.get(filterKey));
                    whereClauses.add(fDesc.getName() + ' = :' + bindVarName);
                    bindIndex++;
                }
            }

            // Validate and build ORDER BY clause
            String orderByClause = '';
            if (String.isNotBlank(orderByField)) {
                SObjectField sField = fieldMap.get(orderByField.trim());
                if (sField == null) {
                    throw new SearchException('Order-by field does not exist: ' + orderByField);
                }
                DescribeFieldResult fDesc = sField.getDescribe();
                if (!fDesc.isSortable()) {
                    throw new SearchException('Order-by field cannot be sorted: ' + orderByField);
                }
                if (!fDesc.isAccessible()) {
                    throw new SearchException('Order-by field is not accessible: ' + orderByField);
                }
                orderByClause = ' ORDER BY ' + fDesc.getName() + ' ASC';
            }

            // Construct SOQL query
            String query = 'SELECT ' + String.join(selectFields, ', ') +
                           ' FROM ' + objDescribe.getName();

            if (!whereClauses.isEmpty()) {
                query += ' WHERE ' + String.join(whereClauses, ' AND ');
            }

            if (String.isNotBlank(orderByClause)) {
                query += orderByClause;
            }

            query += ' LIMIT ' + maxRows;

            // Execute query respecting running user's sharing and FLS
            if (!bindVars.isEmpty()) {
                return Database.queryWithBinds(query, bindVars, AccessLevel.USER_MODE);
            } else {
                return Database.query(query, AccessLevel.USER_MODE);
            }
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            throw new SearchException(e.getMessage(), e);
        }
    }
}
