public with sharing class ContactLookupAction {

    @InvocableMethod(label='Find Contact by Email' description='Finds an existing contact by email address.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        Set<String> cleanEmails = new Set<String>();
        for (Request req : requests) {
            if (req != null && String.isNotBlank(req.email)) {
                cleanEmails.add(req.email.trim().toLowerCase());
            }
        }

        Map<String, Id> emailToContactId = new Map<String, Id>();
        if (!cleanEmails.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :cleanEmails
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                if (String.isNotBlank(c.Email)) {
                    String lowerEmail = c.Email.trim().toLowerCase();
                    if (!emailToContactId.containsKey(lowerEmail)) {
                        emailToContactId.put(lowerEmail, c.Id);
                    }
                }
            }
        }

        for (Request req : requests) {
            Result res = new Result();
            String key = (req != null && String.isNotBlank(req.email)) ? req.email.trim().toLowerCase() : null;
            Id matchedId = (key != null) ? emailToContactId.get(key) : null;

            if (matchedId != null) {
                res.contactId = matchedId;
                res.found = true;
            } else {
                res.contactId = null;
                res.found = false;
            }

            results.add(res);
        }

        return results;
    }

    public class Request {
        @InvocableVariable(label='Email' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact ID')
        public Id contactId;

        @InvocableVariable(label='Found')
        public Boolean found;
    }
}
