public with sharing class OrderPayloadParser {
    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static OrderPayloadParser.Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body cannot be null or blank.');
        }

        Object deserialized;
        try {
            deserialized = JSON.deserializeUntyped(body);
        } catch (Exception ex) {
            throw new PayloadException('Invalid JSON payload: ' + ex.getMessage());
        }

        if (!(deserialized instanceof Map<String, Object>)) {
            throw new PayloadException('Payload must be a JSON object.');
        }

        Map<String, Object> root = (Map<String, Object>) deserialized;

        Object numberObj = root.get('number');
        if (numberObj == null || !(numberObj instanceof String) || String.isBlank((String) numberObj)) {
            throw new PayloadException('Order number is missing or blank.');
        }

        Order order = new Order();
        order.orderNumber = (String) numberObj;

        Object dateObj = root.get('date');
        if (dateObj != null && dateObj instanceof String && String.isNotBlank((String) dateObj)) {
            try {
                order.orderDate = Date.valueOf((String) dateObj);
            } catch (Exception ex) {
                throw new PayloadException('Invalid date format: ' + dateObj);
            }
        }

        Object currObj = root.get('currency');
        if (currObj != null && currObj instanceof String) {
            order.currencyCode = (String) currObj;
        }

        Object custObj = root.get('customer');
        if (custObj instanceof Map<String, Object>) {
            Map<String, Object> custMap = (Map<String, Object>) custObj;
            Object emailObj = custMap.get('email');
            order.customerEmail = emailObj != null ? String.valueOf(emailObj) : null;
        }

        List<Line> parsedLines = new List<Line>();
        Decimal grandTotal = 0;

        Object linesObj = root.get('lines');
        if (linesObj != null) {
            if (!(linesObj instanceof List<Object>)) {
                throw new PayloadException('Lines property must be an array.');
            }

            List<Object> rawLines = (List<Object>) linesObj;
            for (Object lineItem : rawLines) {
                if (!(lineItem instanceof Map<String, Object>)) {
                    throw new PayloadException('Each line item must be a JSON object.');
                }

                Map<String, Object> lineMap = (Map<String, Object>) lineItem;

                Object skuObj = lineMap.get('sku');
                if (skuObj == null || !(skuObj instanceof String) || String.isBlank((String) skuObj)) {
                    throw new PayloadException('Line SKU is missing or blank.');
                }

                Object qtyObj = lineMap.get('quantity');
                if (qtyObj == null) {
                    throw new PayloadException('Line quantity is missing.');
                }

                Integer quantity;
                try {
                    if (qtyObj instanceof Integer) {
                        quantity = (Integer) qtyObj;
                    } else if (qtyObj instanceof Decimal || qtyObj instanceof Long || qtyObj instanceof Double) {
                        quantity = Integer.valueOf(String.valueOf(qtyObj));
                    } else {
                        throw new PayloadException('Invalid quantity type.');
                    }
                } catch (Exception ex) {
                    throw new PayloadException('Invalid quantity: ' + qtyObj);
                }

                if (quantity <= 0) {
                    throw new PayloadException('Line quantity must be positive.');
                }

                Object priceObj = lineMap.get('unitPrice');
                if (priceObj == null) {
                    throw new PayloadException('Line unitPrice is missing.');
                }

                Decimal unitPrice;
                try {
                    if (priceObj instanceof Decimal) {
                        unitPrice = (Decimal) priceObj;
                    } else if (priceObj instanceof Integer || priceObj instanceof Long || priceObj instanceof Double) {
                        unitPrice = Decimal.valueOf(String.valueOf(priceObj));
                    } else {
                        throw new PayloadException('Invalid unitPrice type.');
                    }
                } catch (Exception ex) {
                    throw new PayloadException('Invalid unitPrice: ' + priceObj);
                }

                if (unitPrice < 0) {
                    throw new PayloadException('Line unitPrice cannot be negative.');
                }

                Object discObj = lineMap.get('discount');
                Decimal discount = 0;
                if (discObj != null) {
                    try {
                        if (discObj instanceof Decimal) {
                            discount = (Decimal) discObj;
                        } else if (discObj instanceof Integer || discObj instanceof Long || discObj instanceof Double) {
                            discount = Decimal.valueOf(String.valueOf(discObj));
                        } else {
                            throw new PayloadException('Invalid discount type.');
                        }
                    } catch (Exception ex) {
                        throw new PayloadException('Invalid discount: ' + discObj);
                    }

                    if (discount < 0 || discount > 1) {
                        throw new PayloadException('Discount must be between 0 and 1.');
                    }
                }

                Decimal lineTotal = (Decimal.valueOf(quantity) * unitPrice * (1 - discount)).setScale(2, System.RoundingMode.HALF_UP);
                grandTotal += lineTotal;

                Line line = new Line();
                line.sku = (String) skuObj;
                line.quantity = quantity;
                line.unitPrice = unitPrice;
                line.discount = discount;
                line.lineTotal = lineTotal;
                parsedLines.add(line);
            }
        }

        order.lines = parsedLines;
        order.total = grandTotal;

        return order;
    }

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        Map<String, Object> ack = new Map<String, Object>{
            'number' => order != null ? order.orderNumber : null,
            'status' => 'RECEIVED',
            'lineCount' => (order != null && order.lines != null) ? order.lines.size() : 0,
