public inherited sharing class PicklistService {

    public class PicklistServiceException extends Exception {}

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option() {}

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name must not be null or blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name must not be null or blank.');
        }

        try {
            Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
            Schema.SObjectType sObjectType = globalDescribe.get(objectApiName.toLowerCase());
            if (sObjectType == null) {
                sObjectType = globalDescribe.get(objectApiName);
            }
            if (sObjectType == null) {
                throw new PicklistServiceException('Object does not exist: ' + objectApiName);
            }

            Map<String, Schema.SObjectField> fieldMap = sObjectType.getDescribe().fields.getMap();
            Schema.SObjectField sObjectField = fieldMap.get(fieldApiName);
            if (sObjectField == null) {
                sObjectField = fieldMap.get(fieldApiName.toLowerCase());
            }
            if (sObjectField == null) {
                throw new PicklistServiceException('Field does not exist on object: ' + fieldApiName);
            }

            Schema.DescribeFieldResult fieldDescribe = sObjectField.getDescribe();
            Schema.DisplayType displayType = fieldDescribe.getType();
            if (displayType != Schema.DisplayType.PICKLIST && displayType != Schema.DisplayType.MULTIPICKLIST) {
                throw new PicklistServiceException('Field is not a picklist or multi-select picklist: ' + fieldApiName);
            }

            List<PicklistService.Option> options = new List<PicklistService.Option>();
            for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
                if (entry.isActive()) {
                    options.add(new PicklistService.Option(
                        entry.getValue(),
                        entry.getLabel(),
                        entry.isDefaultValue()
                    ));
                }
            }

            return options;
        } catch (PicklistServiceException pse) {
            throw pse;
        } catch (Exception ex) {
            throw new PicklistServiceException(ex.getMessage(), ex);
        }
    }
}
