public without sharing class OpportunityPipelineHandler {
    private static Boolean isRecalculating = false;

    public static void handleAfterInsert(List<Opportunity> newOpps) {
        Set<Id> accountIds = new Set<Id>();
        if (newOpps != null) {
            for (Opportunity opp : newOpps) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
            }
        }
        recalculateAccounts(accountIds);
    }

    public static void handleAfterUpdate(List<Opportunity> newOpps, Map<Id, Opportunity> oldOppMap) {
        Set<Id> accountIds = new Set<Id>();
        if (newOpps != null && oldOppMap != null) {
            for (Opportunity newOpp : newOpps) {
                Opportunity oldOpp = oldOppMap.get(newOpp.Id);
                if (oldOpp == null) {
                    continue;
                }

                Boolean amountChanged = (newOpp.Amount != oldOpp.Amount);
                Boolean stageChanged = (newOpp.IsClosed != oldOpp.IsClosed);
                Boolean accountChanged = (newOpp.AccountId != oldOpp.AccountId);

                if (amountChanged || stageChanged || accountChanged) {
                    if (newOpp.AccountId != null) {
                        accountIds.add(newOpp.AccountId);
                    }
                    if (oldOpp.AccountId != null) {
                        accountIds.add(oldOpp.AccountId);
                    }
                }
            }
        }
        recalculateAccounts(accountIds);
    }

    public static void handleAfterDelete(List<Opportunity> oldOpps) {
        Set<Id> accountIds = new Set<Id>();
        if (oldOpps != null) {
            for (Opportunity opp : oldOpps) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
            }
        }
        recalculateAccounts(accountIds);
    }

    public static void handleAfterUndelete(List<Opportunity> newOpps) {
        Set<Id> accountIds = new Set<Id>();
        if (newOpps != null) {
            for (Opportunity opp : newOpps) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
            }
        }
        recalculateAccounts(accountIds);
    }

    public static void recalculateAccounts(Set<Id> accountIds) {
        if (isRecalculating || accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Set<Id> validAccountIds = new Set<Id>(accountIds);
        validAccountIds.remove(null);
        if (validAccountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Id accId : validAccountIds) {
            accountsToUpdate.put(accId, new Account(
                Id = accId,
                FB_Open_Pipeline__c = 0,
                FB_Open_Opportunities__c = 0
            ));
        }

        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) totalAmount, COUNT(Id) totalCount
            FROM Opportunity
            WHERE AccountId IN :validAccountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('AccountId');
            Decimal totalAmount = (Decimal) ar.get('totalAmount');
            Integer totalCount = (Integer) ar.get('totalCount');

            Account acc = accountsToUpdate.get(accId);
            if (acc != null) {
                acc.FB_Open_Pipeline__c = (totalAmount != null) ? totalAmount : 0;
                acc.FB_Open_Opportunities__c = (totalCount != null) ? totalCount : 0;
            }
        }

        Map<Id, Account> currentAccounts = new Map<Id, Account>([
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountsToUpdate.keySet()
        ]);

        List<Account> changedAccounts = new List<Account>();
        for (Account acc : accountsToUpdate.values()) {
            Account current = currentAccounts.get(acc.Id);
            if (current != null && (
                current.FB_Open_Pipeline__c != acc.FB_Open_Pipeline__c ||
                current.FB_Open_Opportunities__c != acc.FB_Open_Opportunities__c
            )) {
                changedAccounts.add(acc);
            }
        }

        if (!changedAccounts.isEmpty()) {
            isRecalculating = true;
            try {
                update changedAccounts;
            } finally {
                isRecalculating = false;
            }
        }
    }
}
