public with sharing class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext ctx) {
        DateTime cutoff30 = DateTime.now().addDays(-30);
        DateTime cutoff180 = DateTime.now().addDays(-180);

        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (Level__c = 'ERROR' AND CreatedDate < :cutoff180)
               OR (Level__c != 'ERROR' AND CreatedDate < :cutoff30)
               OR (Level__c = null AND CreatedDate < :cutoff30)
        ];

        if (!logsToDelete.isEmpty()) {
            delete logsToDelete;
        }
    }

    public static Id scheduleNightly() {
        return System.schedule('Log purge (nightly)', '0 0 2 * * ?', new LogPurgeJob());
    }
}
