public with sharing class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> wonAmountByAccountId = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return wonAmountByAccountId;
        }

        for (Id accountId : accountIds) {
            if (accountId != null) {
                wonAmountByAccountId.put(accountId, 0);
            }
        }

        if (wonAmountByAccountId.isEmpty()) {
            return wonAmountByAccountId;
        }

        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :wonAmountByAccountId.keySet()
              AND IsWon = true
              AND CloseDate = THIS_YEAR
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) ar.get('AccountId');
            Decimal totalAmount = (Decimal) ar.get('totalAmount');
            wonAmountByAccountId.put(accountId, totalAmount != null ? totalAmount : 0);
        }

        return wonAmountByAccountId;
    }
}
