public inherited sharing class ContactPhoneCleanup {
    /**
     * Normalizes phone numbers for the provided contacts by removing all characters
     * that are not digits or a leading/contained '+'. Contacts without a phone are skipped.
     *
     * @param contactIds List of Contact IDs to process.
     * @return Map of Contact ID to the first error message for any records that failed to save.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorMap = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errorMap;
        }

        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact c : [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds AND Phone != null
        ]) {
            c.Phone = c.Phone.replaceAll('[^0-9+]', '');
            contactsToUpdate.add(c);
        }

        if (contactsToUpdate.isEmpty()) {
            return errorMap;
        }

        Database.SaveResult[] saveResults = Database.update(contactsToUpdate, false);
        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult sr = saveResults[i];
            if (!sr.isSuccess()) {
                Database.Error[] errors = sr.getErrors();
                String message = (errors != null && !errors.isEmpty())
                    ? errors[0].getMessage()
                    : 'Unknown error occurred while updating record.';
                errorMap.put(contactsToUpdate[i].Id, message);
            }
        }

        return errorMap;
    }
}
