public with sharing class PipelineSummary {
    private static final List<String> TARGET_STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    /**
     * Calculates the sum of Opportunity Amount for each of the four open stages
     * within the specified CloseDate range (inclusive).
     *
     * Uses a single aggregate query with GROUP BY instead of looping queries to
     * minimize governor limit usage and avoid unnecessary database round-trips.
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        Map<String, Decimal> summary = new Map<String, Decimal>{
            'Prospecting' => 0,
            'Qualification' => 0,
            'Proposal/Price Quote' => 0,
            'Negotiation/Review' => 0
        };

        if (fromDate == null || toDate == null) {
            return summary;
        }

        for (AggregateResult ar : [
            SELECT StageName, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE StageName IN :TARGET_STAGES
              AND CloseDate >= :fromDate
              AND CloseDate <= :toDate
            GROUP BY StageName
        ]) {
            String stage = (String) ar.get('StageName');
            Decimal total = (Decimal) ar.get('totalAmount');
            summary.put(stage, total != null ? total : 0);
        }

        return summary;
    }
}
