public with sharing class StaleOpportunityCloser {
    /**
     * Closes open opportunities with a CloseDate strictly prior to the cutoff date.
     * Updates records in chunks of 200 via a SOQL list-iteration loop.
     *
     * @param cutoff Date threshold; opportunities closing before this date are closed lost.
     * @return Total count of opportunities updated.
     */
    public static Integer closeStale(Date cutoff) {
        if (cutoff == null) {
            return 0;
        }

        Integer totalClosed = 0;

        for (List<Opportunity> chunk : [
            SELECT Id
            FROM Opportunity
            WHERE IsClosed = false
              AND CloseDate < :cutoff
        ]) {
            for (Opportunity opp : chunk) {
                opp.StageName = 'Closed Lost';
            }
            update chunk;
            totalClosed += chunk.size();
        }

        return totalClosed;
    }
}
