            return new List<Database.SaveResult>();
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();
        for (Opportunity opp : opportunities) {
            events.add(new Deal_Stage_Change__e(
                Opportunity_Id__c = opp.Id,
                Stage__c = opp.StageName,
                Amount__c = opp.Amount
            ));
        }

        // Deviating from calling EventBus.publish per record in a loop:
        // Calling EventBus.publish per record for up to 200 records exceeds the 150 DML statement limit.
        // EventBus.publish(List<SObject>) executes in a single DML call and returns SaveResults
        // in the exact same index order, identifying failures per event safely.
        return EventBus.publish(events);
    }
}
