            Boolean stageChanged = opp.StageName != oldOpp.StageName;
            Boolean amountChanged = opp.Amount != oldOpp.Amount;
            Boolean accountChanged = opp.AccountId != oldOpp.AccountId;

            if (stageChanged || amountChanged || accountChanged) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
                if (accountChanged && oldOpp.AccountId != null) {
                    accountIds.add(oldOpp.AccountId);
                }
            }
        }
    }

    if (!accountIds.isEmpty()) {
        if (System.isFuture() || System.isBatch()) {
            AccountRatingService.recalculateAccounts(accountIds);
        } else {
            AccountRatingService.recalculate(accountIds);
        }
    }
