public without sharing class AccountRatingService {

    @future
    public static void recalculate(Set<Id> accountIds) {
        recalculateAccounts(accountIds);
    }

    public static void recalculateAccounts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :accountIds
        ]);

        if (accountsById.isEmpty()) {
            return;
        }

        Set<Id> accountsWithOpenOpps = new Set<Id>();
        Map<Id, Decimal> maxAmountByAccountId = new Map<Id, Decimal>();

        for (AggregateResult ar : [
            SELECT AccountId, MAX(Amount) maxAmount
            FROM Opportunity
            WHERE AccountId IN :accountsById.keySet()
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('AccountId');
            Decimal maxAmount = (Decimal) ar.get('maxAmount');
            accountsWithOpenOpps.add(accId);
            maxAmountByAccountId.put(accId, maxAmount);
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Account acc : accountsById.values()) {
            String targetRating;

            if (accountsWithOpenOpps.contains(acc.Id)) {
                Decimal maxAmount = maxAmountByAccountId.get(acc.Id);
                if (maxAmount != null && maxAmount >= 100000) {
                    targetRating = 'Hot';
                } else {
                    targetRating = 'Warm';
                }
            } else {
                targetRating = 'Cold';
            }

            if (acc.Rating != targetRating) {
                acc.Rating = targetRating;
                accountsToUpdate.add(acc);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
```

