```apex
public with sharing class AccountCountrySync {
    public static void syncContactCountry(List<Account> newAccounts, Map<Id, Account> oldAccountsMap) {
        if (newAccounts == null || oldAccountsMap == null) {
            return;
        }

        Map<Id, Account> changedAccounts = new Map<Id, Account>();
        for (Account acc : newAccounts) {
            Account oldAcc = oldAccountsMap.get(acc.Id);
            if (oldAcc != null && acc.BillingCountry != oldAcc.BillingCountry) {
                changedAccounts.put(acc.Id, acc);
            }
        }

        if (changedAccounts.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact con : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccounts.keySet()
        ]) {
            Account newAcc = changedAccounts.get(con.AccountId);
            Account oldAcc = oldAccountsMap.get(con.AccountId);

            if (String.isBlank(con.MailingCountry) ||
                (String.isNotBlank(oldAcc.BillingCountry) && con.MailingCountry.equalsIgnoreCase(oldAcc.BillingCountry))) {
                con.MailingCountry = newAcc.BillingCountry;
                contactsToUpdate.add(con);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
