import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    stats;
    errorMessage;
    isInFlight = false;
    intervalId = null;
    isComponentConnected = false;

    get waiting() {
        return this.stats?.waiting;
    }

    get longestWaitMinutes() {
        return this.stats?.longestWaitMinutes;
    }

    get hasStats() {
        return Boolean(this.stats);
    }

    get isDocumentHidden() {
        return typeof document !== 'undefined' && document.visibilityState === 'hidden';
    }

    connectedCallback() {
        this.isComponentConnected = true;
        document.addEventListener('visibilitychange', this.handleVisibilityChange);
        if (!this.isDocumentHidden) {
            this.startPolling();
        }
    }

    disconnectedCallback() {
        this.isComponentConnected = false;
        this.stopPolling();
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    }

    handleVisibilityChange = () => {
        if (!this.isComponentConnected) {
            return;
        }
        if (this.isDocumentHidden) {
            this.stopPolling();
        } else {
            this.startPolling();
        }
    };

    startPolling() {
        this.stopPolling();
        this.fetchStats();
        this.intervalId = setInterval(() => {
            this.fetchStats();
        }, REFRESH_INTERVAL_MS);
    }

    stopPolling() {
        if (this.intervalId) {
            clearInterval(this.intervalId);
            this.intervalId = null;
        }
    }

    async fetchStats() {
        if (this.isDocumentHidden || this.isInFlight) {
            return;
        }

        this.isInFlight = true;
        try {
            const data = await getQueueStats();
            if (!this.isComponentConnected) {
                return;
            }
            this.stats = data;
            this.errorMessage = null;
        } catch (error) {
            if (!this.isComponentConnected) {
                return;
            }
            this.errorMessage = error?.body?.message || error?.message;
        } finally {
            this.isInFlight = false;
        }
    }
}
