import { LightningElement, api } from 'lwc';

const HANDLED_KEYS = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value = '';
    activeIndex = 0;

    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = Array.isArray(val) ? val : [];
        this.syncActiveFromValue();
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        this.syncActiveFromValue();
    }

    syncActiveFromValue() {
        if (!this._options || this._options.length === 0) {
            this.activeIndex = 0;
            return;
        }
        const hasSelection = this._value !== undefined && this._value !== null && this._value !== '';
        if (hasSelection) {
            const index = this._options.findIndex(opt => opt.value === this._value);
            this.activeIndex = index !== -1 ? index : 0;
        } else {
            this.activeIndex = 0;
        }
    }

    get activeDescendantId() {
        if (this._options && this._options.length > 0 && this.activeIndex >= 0 && this.activeIndex < this._options.length) {
            return `option-${this.activeIndex}`;
        }
        return undefined;
    }

    get computedOptions() {
        const hasSelection = this._value !== undefined && this._value !== null && this._value !== '';
        return (this._options || []).map((option, index) => {
            const isSelected = hasSelection ? option.value === this._value : false;
            return {
                ...option,
                id: `option-${index}`,
                index,
                ariaSelected: isSelected ? 'true' : 'false'
            };
        });
    }

    handleKeyDown(event) {
        if (!HANDLED_KEYS.includes(event.key)) {
            return;
        }

        event.preventDefault();

        if (!this._options || this._options.length === 0) {
            return;
        }

        switch (event.key) {
            case 'ArrowDown':
                if (this.activeIndex < this._options.length - 1) {
                    this.activeIndex++;
                }
                break;
            case 'ArrowUp':
                if (this.activeIndex > 0) {
                    this.activeIndex--;
                }
                break;
            case 'Home':
                this.activeIndex = 0;
                break;
            case 'End':
                this.activeIndex = this._options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this.selectActiveOption();
                break;
            default:
                break;
        }
    }

    selectActiveOption() {
        if (this.activeIndex >= 0 && this.activeIndex < this._options.length) {
            const option = this._options[this.activeIndex];
            this.selectOption(option.value);
        }
    }

    handleOptionClick(event) {
        const index = parseInt(event.currentTarget.dataset.index, 10);
        if (!isNaN(index) && index >= 0 && index < this._options.length) {
            this.activeIndex = index;
            const option = this._options[index];
            this.selectOption(option.value);
        }
    }

    selectOption(val) {
        if (this._value !== val) {
            this._value = val;
            this.dispatchEvent(
                new CustomEvent('change', {
                    detail: { value: val }
                })
            );
        }
    }
}
