        this.newLabel = event.detail.value ?? event.target.value ?? '';
    }

    handleAdd() {
        const label = this.newLabel ? this.newLabel.trim() : '';
        if (!label) {
            return;
        }

        const newTask = {
            id: `new-${this.nextId++}`,
            label,
            done: false
        };

        this.items = [...this.items, newTask];
        this.newLabel = '';

        const input = this.template.querySelector('.new-task');
        if (input) {
            input.value = '';
        }

        this.dispatchEvent(
            new CustomEvent('taskadded', {
                detail: { label }
            })
        );
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        this.items = this.items.map((task) => {
            if (String(task.id) === id) {
                return { ...task, done: !task.done };
            }
            return task;
        });
    }
