public with sharing class HouseholdService {
    /**
     * Creates a single NPSP Household Account for the given contacts,
     * assigning the first contact as the household's primary contact.
     *
     * @param members List of new contacts to add to the household.
     * @return Id of the created Household Account.
     * @throws IllegalArgumentException if members is null or empty.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('Members list cannot be null or empty.');
        }

        for (Contact member : members) {
            if (member == null) {
                throw new IllegalArgumentException('Member contacts cannot be null.');
            }
        }

        Id householdRecordTypeId = Schema.SObjectType.Account.getRecordTypeInfosByDeveloperName()
            .get('HH_Account')
            .getRecordTypeId();

        Account household = new Account(
            RecordTypeId = householdRecordTypeId
        );
        insert household;

        for (Contact member : members) {
            member.AccountId = household.Id;
        }
        insert members;

        household.npe01__One2OneContact__c = members[0].Id;
        update household;

        return household.Id;
    }
}
