public inherited sharing class SoftCreditService {
    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();

        for (SoftCreditRequest req : requests) {
            if (req == null) {
                throw new SoftCreditException('Request cannot be null.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Soft credit amount must be greater than zero.');
            }
            if (req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('Opportunity ID and Contact ID are required.');
            }
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // Query 1: Opportunities to validate primary contact and amounts
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
        ]);

        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found for ID: ' + req.opportunityId);
            }
            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'Contact ' + req.contactId + ' is the primary contact on Opportunity ' + req.opportunityId
                );
            }
            if (opp.Amount == null || req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Soft credit amount ' + req.amount + ' cannot exceed the opportunity amount (' + opp.Amount + ').'
                );
            }
        }

        // Query 2: Existing OpportunityContactRoles for the targeted opportunities and contacts
        List<OpportunityContactRole> existingOcrs = [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
        ];

        Map<String, List<OpportunityContactRole>> ocrsByOppContact = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : existingOcrs) {
            String key = ocr.OpportunityId + ':' + ocr.ContactId;
            List<OpportunityContactRole> ocrList = ocrsByOppContact.get(key);
            if (ocrList == null) {
                ocrList = new List<OpportunityContactRole>();
                ocrsByOppContact.put(key, ocrList);
            }
            ocrList.add(ocr);
        }

        // Query 3: Existing Partial Soft Credits for the targeted opportunities and contacts
        List<npsp__Partial_Soft_Credit__c> existingPscs = [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c, npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ];

        Map<String, npsp__Partial_Soft_Credit__c> pscsByOppContact = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : existingPscs) {
            String key = psc.npsp__Opportunity__c + ':' + psc.npsp__Contact__c;
            if (!pscsByOppContact.containsKey(key)) {
                pscsByOppContact.put(key, psc);
            }
        }

        List<OpportunityContactRole> ocrsToDelete = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToUpdate = new List<OpportunityContactRole>();
        Map<SoftCreditRequest, OpportunityContactRole> reqToOcr = new Map<SoftCreditRequest, OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + ':' + req.contactId;
            List<OpportunityContactRole> ocrList = ocrsByOppContact.get(key);
            OpportunityContactRole targetOcr;

            if (ocrList != null && !ocrList.isEmpty()) {
                targetOcr = ocrList[0];
                if (targetOcr.Role != req.role) {
                    targetOcr.Role = req.role;
                    ocrsToUpdate.add(targetOcr);
                }
                // Ensure the contact has exactly one OCR on this opportunity
                for (Integer i = 1; i < ocrList.size(); i++) {
                    ocrsToDelete.add(ocrList[i]);
                }
            } else {
                targetOcr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                ocrsToInsert.add(targetOcr);
            }
            reqToOcr.put(req, targetOcr);
        }

        // DML on OpportunityContactRole
        if (!ocrsToDelete.isEmpty()) {
            delete ocrsToDelete;
        }
        if (!ocrsToInsert.isEmpty()) {
            insert ocrsToInsert;
        }
        if (!ocrsToUpdate.isEmpty()) {
            update ocrsToUpdate;
        }

        // Build Partial Soft Credit records
        List<npsp__Partial_Soft_Credit__c> pscsToUpsert = new List<npsp__Partial_Soft_Credit__c>();
        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + ':' + req.contactId;
            OpportunityContactRole ocr = reqToOcr.get(req);
            npsp__Partial_Soft_Credit__c psc = pscsByOppContact.get(key);

            if (psc != null) {
                psc.npsp__Amount__c = req.amount;
                psc.npsp__Role_Name__c = req.role;
                psc.npsp__Contact_Role_ID__c = String.valueOf(ocr.Id);
                pscsToUpsert.add(psc);
            } else {
                pscsToUpsert.add(new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = String.valueOf(ocr.Id)
                ));
            }
        }

        // DML on Partial Soft Credits
        if (!pscsToUpsert.isEmpty()) {
            upsert pscsToUpsert;
        }
    }
}
