global without sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert &&
            triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return dmlWrapper;
        }

        List<Task> tasksToInsert = new List<Task>();

        if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert) {
            for (SObject sobj : newlist) {
                Opportunity opp = (Opportunity) sobj;
                if (isMajorGift(opp)) {
                    tasksToInsert.add(createFollowUpTask(opp));
                }
            }
        } else if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
            Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>();
            if (oldlist != null) {
                for (SObject sobj : oldlist) {
                    Opportunity oldOpp = (Opportunity) sobj;
                    if (oldOpp.Id != null) {
                        oldMap.put(oldOpp.Id, oldOpp);
                    }
                }
            }

            for (Integer i = 0; i < newlist.size(); i++) {
                Opportunity opp = (Opportunity) newlist[i];
                Opportunity oldOpp = null;
                if (opp.Id != null && oldMap.containsKey(opp.Id)) {
                    oldOpp = oldMap.get(opp.Id);
                } else if (oldlist != null && i < oldlist.size()) {
                    oldOpp = (Opportunity) oldlist[i];
                }

                if (isMajorGift(opp) && !isMajorGift(oldOpp)) {
                    tasksToInsert.add(createFollowUpTask(opp));
                }
            }
        }

        if (!tasksToInsert.isEmpty()) {
            if (dmlWrapper.objectsToInsert == null) {
                dmlWrapper.objectsToInsert = new List<SObject>();
            }
            dmlWrapper.objectsToInsert.addAll(tasksToInsert);
        }

        return dmlWrapper;
    }

    private Boolean isMajorGift(Opportunity opp) {
        if (opp == null) {
            return false;
        }
        Boolean isWon = (opp.IsWon == true || opp.StageName == 'Closed Won');
        Boolean hasMajorAmount = (opp.Amount != null && opp.Amount >= 5000);
        return isWon && hasMajorAmount;
    }

    private Task createFollowUpTask(Opportunity opp) {
        return new Task(
            Subject = 'Major gift thank-you call',
            Priority = 'High',
            Status = 'Not Started',
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId,
            ActivityDate = opp.CloseDate != null ? opp.CloseDate.addDays(3) : null
        );
    }
}
