```apex
public with sharing class RecordAccessService {
    private static final Integer MAX_RECORDS_PER_QUERY = 200;

    /**
     * Returns the subset of recordIds that the running user can edit,
     * as reported by UserRecordAccess (HasEditAccess).
     *
     * @param recordIds Set of record IDs to check access for.
     * @return Set of record IDs the running user has edit access to (never null).
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editableRecordIds = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editableRecordIds;
        }

        List<Id> validIds = new List<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                validIds.add(recordId);
            }
        }

        if (validIds.isEmpty()) {
            return editableRecordIds;
        }

        Id currentUserId = UserInfo.getUserId();
        Integer totalRecords = validIds.size();

        for (Integer i = 0; i < totalRecords; i += MAX_RECORDS_PER_QUERY) {
            List<Id> chunk = new List<Id>();
            Integer endIndex = Math.min(i + MAX_RECORDS_PER_QUERY, totalRecords);
            for (Integer j = i; j < endIndex; j++) {
                chunk.add(validIds[j]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :currentUserId
                  AND RecordId IN :chunk
            ]) {
                if (access.HasEditAccess) {
                    editableRecordIds.add(access.RecordId);
                }
            }
        }

        return editableRecordIds;
    }
}
