    public static Set<Id> opportunityIds {
        get {
            return OpportunityErpSyncFinalizer.opportunityIdsToSync;
        }
        set {
            OpportunityErpSyncFinalizer.opportunityIdsToSync = value;
        }
    }

    public void afterInsert(List<SObject> triggerNew) {
        if (triggerNew == null) {
            return;
        }
        for (Opportunity opp : (List<Opportunity>) triggerNew) {
            if (opp.Id != null) {
                OpportunityErpSyncFinalizer.opportunityIdsToSync.add(opp.Id);
            }
        }
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        if (triggerNew == null || triggerOld == null) {
            return;
        }
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity newOpp = (Opportunity) triggerNew[i];
            Opportunity oldOpp = (Opportunity) triggerOld[i];
            if (newOpp.Id != null && newOpp.StageName != oldOpp.StageName) {
                OpportunityErpSyncFinalizer.opportunityIdsToSync.add(newOpp.Id);
            }
        }
    }
}
