@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {
    @IsTest
    static void beforeUpdate_reductionMoreThanHalf_addsError() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldOpp = new Opportunity(Id = oppId, Amount = 1000);
        Opportunity newOpp = new Opportunity(Id = oppId, Amount = 499);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        Assert.isTrue(newOpp.hasErrors(), 'Opportunity should have errors when amount is reduced by more than half.');
        Assert.areEqual(1, newOpp.getErrors().size(), 'Opportunity should have exactly one error.');
        Assert.areEqual(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            newOpp.getErrors()[0].getMessage(),
            'Error message should match ERROR_MESSAGE constant.'
        );
    }

    @IsTest
    static void beforeUpdate_reductionExactlyHalf_noError() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldOpp = new Opportunity(Id = oppId, Amount = 1000);
        Opportunity newOpp = new Opportunity(Id = oppId, Amount = 500);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        Assert.isFalse(newOpp.hasErrors(), 'Opportunity should not have errors when amount is reduced by exactly half.');
    }

    @IsTest
    static void beforeUpdate_amountIncreased_noError() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldOpp = new Opportunity(Id = oppId, Amount = 1000);
        Opportunity newOpp = new Opportunity(Id = oppId, Amount = 1500);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        Assert.isFalse(newOpp.hasErrors(), 'Opportunity should not have errors when amount is increased.');
    }

    @IsTest
    static void beforeUpdate_previousAmountNull_noError() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldOpp = new Opportunity(Id = oppId, Amount = null);
        Opportunity newOpp = new Opportunity(Id = oppId, Amount = 500);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        Assert.isFalse(newOpp.hasErrors(), 'Opportunity with null previous amount should not have errors.');
    }

    @IsTest
    static void beforeUpdate_multipleRecords_onlyViolatingRecordsHaveErrors() {
        Id oppId1 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id oppId2 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id oppId3 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id oppId4 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id oppId5 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        // Record 1: > 50% decrease (1000 -> 400) => violates rule
        Opportunity oldOpp1 = new Opportunity(Id = oppId1, Amount = 1000);
        Opportunity newOpp1 = new Opportunity(Id = oppId1, Amount = 400);

        // Record 2: exactly 50% decrease (1000 -> 500) => valid
        Opportunity oldOpp2 = new Opportunity(Id = oppId2, Amount = 1000);
        Opportunity newOpp2 = new Opportunity(Id = oppId2, Amount = 500);

        // Record 3: increase (1000 -> 2000) => valid
        Opportunity oldOpp3 = new Opportunity(Id = oppId3, Amount = 1000);
        Opportunity newOpp3 = new Opportunity(Id = oppId3, Amount = 2000);

        // Record 4: > 50% decrease (800 -> 300) => violates rule
        Opportunity oldOpp4 = new Opportunity(Id = oppId4, Amount = 800);
        Opportunity newOpp4 = new Opportunity(Id = oppId4, Amount = 300);

        // Record 5: previous Amount is null => valid
        Opportunity oldOpp5 = new Opportunity(Id = oppId5, Amount = null);
